package com.example.rokidgeminisecretary;
import android.app.*;import android.content.*;import android.net.Uri;import android.widget.*;import org.json.*;
final class LokiUpdateDialog {
 static void show(MainActivity owner){try{JSONObject phone=InstallationIdentity.snapshot(owner),workspace=ConversationWorkspace.snapshot(owner),glass=workspace.optJSONObject("installation"),capture=workspace.optJSONObject("capture");boolean fresh=workspace.optBoolean("connected");LinearLayout box=new LinearLayout(owner);box.setOrientation(1);TextView status=new TextView(owner);status.setText("GitHubの公開情報を確認します。APKの取得・インストールは自動で行いません。");box.addView(status);add(owner,box,"このスマホ：v"+phone.optLong("version")+"\n"+UpdatePolicy.compatibility(phone)+"\nメガネ："+(fresh&&glass!=null?"v"+glass.optLong("version")+"\n"+UpdatePolicy.compatibility(glass):"版・署名・接続が未確認です"));long free=owner.getFilesDir().getUsableSpace();add(owner,box,"スマホの空き容量："+free/1048576+" MiB"+(free<600000000?"（容量を確認してください）":"")+"\nメガネの録音・撮影："+(!fresh||capture==null?"現在は未確認":capture.optBoolean("meetingService")||capture.optBoolean("keepService")?"稼働の報告があります。停止してから更新してください":"直近の報告では停止しています。更新直前にも確認してください"));long backup=owner.getSharedPreferences("loki-update-notices",0).getLong("backupWrittenAt",0);add(owner,box,"バックアップ："+(backup>0?new java.util.Date(backup)+"に暗号化ファイルを書き出しました（復元は未検証）":"この画面で確認できる書き出し記録はありません")+"\n既存の書き出し機能はメモ・記憶の参照コピー・保守画面設定が対象です。写真・録音・会話全文・認証情報・参照セット・メガネ辞書は含みません。必要な記録は個別にも保存してください。");Button backupButton=new Button(owner);backupButton.setText("バックアップの対象を確認して保存");backupButton.setOnClickListener(v->new MaintenanceBackupUi(owner).show());box.addView(backupButton);CheckBox daily=new CheckBox(owner);daily.setText("アプリ起動時に1日1回、GitHubで更新を確認する");daily.setChecked(LokiUpdates.prefs(owner).getBoolean("daily",false));daily.setOnCheckedChangeListener((v,enabled)->LokiUpdates.prefs(owner).edit().putBoolean("daily",enabled).commit());box.addView(daily);Button check=new Button(owner);check.setText("今すぐ更新を確認");box.addView(check);LinearLayout releaseBox=new LinearLayout(owner);releaseBox.setOrientation(1);box.addView(releaseBox);JSONObject cached=LokiUpdates.cached(owner);if(cached!=null)render(owner,releaseBox,cached,phone,fresh?glass:null);ScrollView scroll=new ScrollView(owner);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("アプリ更新・更新前チェック").setView(scroll).setPositiveButton("閉じる",null).create();check.setOnClickListener(v->{check.setEnabled(false);status.setText("GitHubの公開版を確認しています…");new Thread(()->{try{JSONObject result=LokiUpdates.check(owner);owner.runOnUiThread(()->{if(!dialog.isShowing())return;render(owner,releaseBox,result,phone,fresh?glass:null);status.setText(UpdatePolicy.newer(result,phone,fresh?glass:null)?"新しい版があります。対象と署名、記録の保存を確認してください。":"確認した公開版と、取得できた端末の版を表示しています。");});}catch(Exception e){owner.runOnUiThread(()->{if(dialog.isShowing())status.setText(e.getMessage()+"。表示済みの情報は以前の確認結果の場合があります。");});}finally{owner.runOnUiThread(()->check.setEnabled(true));}},"LokiExplicitUpdateCheck").start();});dialog.show();}catch(Exception e){new AlertDialog.Builder(owner).setMessage("更新前の状態を確認できません。更新・削除は行っていません。").setPositiveButton("閉じる",null).show();}}
 private static void add(MainActivity owner,LinearLayout box,String text){TextView view=new TextView(owner);view.setText(text);view.setTextIsSelectable(true);view.setPadding(16,12,16,12);box.addView(view);}
 private static void render(MainActivity owner,LinearLayout box,JSONObject release,JSONObject phone,JSONObject glass){box.removeAllViews();add(owner,box,"確認した公開版："+release.optString("tag")+(release.optBoolean("prerelease")?"（アルファ・プレビュー版）":"")+"\n確認日時："+new java.util.Date(release.optLong("checkedAt")));for(String kind:new String[]{"phone","glass"}){JSONObject apk=release.optJSONObject(kind);if(apk!=null)add(owner,box,(kind.equals("phone")?"スマホ用":"メガネ用")+"："+apk.optString("name")+"\n"+apk.optLong("bytes")/1048576+" MiB / SHA256："+apk.optString("sha256"));}add(owner,box,"SHA256はGitHubが公開するファイルの値です。この画面は取得後のAPKの署名・内容を検証したものではありません。開発署名版へ配布APKは上書きできません。署名を変えるためにアンインストールすると記録や復号鍵を失う場合があります。");Button open=new Button(owner);open.setText("GitHubの説明・対応APKを開く");open.setOnClickListener(v->{String url=release.optString("url");if(url.equals(UpdatePolicy.BASE+"tag/"+release.optString("tag"))&&release.optString("tag").matches("glass-v[1-9][0-9]{0,5}"))owner.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));});box.addView(open);}
 private LokiUpdateDialog(){}
}
